a83a2904.png","mimeType":"image/png","byteSize":1898700,"width":1741,"height":1654,"publicUrl":"https://mczhcwtlldhbmrgiggjl.supabase.co/storage/v1/object/public/place-media/e5343163-2799-4501-b5d4-ce0c9d10161b/brand-c7f1e1447b3aa83a2904.png","altText":"巴黎贝甜品牌菜品图：草莓奶油羊角面包（具体门店供应以实际为准）；来源：巴黎贝甜中国官网；https://pbchina.cn/index.php/detail/jqjx/706","reusePermission":"not independently confirmed; public source and credit retained"},{"file":"kuafood-brand-product.jpg","placeId":"af253498-5278-4e25-b4ec-f32617ace455","title":"夸父炸串品牌菜品图：巴掌大鸡排（品牌宣传图）","sourcePageUrl":"https://www.kuafood.com/","imageUrl":"https://oss-cdn.kuafood.com/74/68/03055f688f35b5b485e6304ec90240b977f2db0abe490f6859ae7494adbd.jpg","credit":"夸父炸串品牌官网","branchEvidence":"官网主打产品区域明确巴掌大鸡排；非励骏庞都分店实拍","photoType":"brand-product","sortOrder":0,"sha256":"746803055f688f35b5b485e6304ec90240b977f2db0abe490f6859ae7494adbd","storagePath":"af253498-5278-4e25-b4ec-f32617ace455/brand-746803055f688f35b5b4.jpg","mimeType":"image/jpeg","byteSize":127928,"width":500,"height":330,"publicUrl":"https://mczhcwtlldhbmrgiggjl.supabase.co/storage/v1/object/public/place-media/af253498-5278-4e25-b4ec-f32617ace455/brand-746803055f688f35b5b4.jpg","altText":"夸父炸串品牌菜品图：巴掌大鸡排（品牌宣传图）；来源：夸父炸串品牌官网；https://www.kuafood.com/","reusePermission":"not independently confirmed; public source and credit retained"},{"file":"xijie-brand-product.jpeg","placeId":"079ade24-56d4-4728-8f43-e99807811b7a","title":"喜姐炸串品牌菜品图：酱汁臭豆腐（品牌宣传图）","sourcePageUrl":"https://www.xijiezhachuan.com/","imageUrl":"https://prd-coreserver-cdn.xijie888.com/website/imags/choudoufu.jpeg","credit":"喜姐炸串品牌官网","branchEvidence":"官网主打产品图片alt明确酱汁臭豆腐；非横琴分店实拍","photoType":"brand-product","sortOrder":0,"sha256":"f469e29d2e0c2a89fb411cff7d62f0fcd3981474ad75b44dc71ffc394db843ee","storagePath":"079ade24-56d4-4728-8f43-e99807811b7a/brand-f469e29d2e0c2a89fb41.jpg","mimeType":"image/jpeg","byteSize":677570,"width":1200,"height":900,"publicUrl":"https://mczhcwtlldhbmrgiggjl.supabase.co/storage/v1/object/public/place-media/079ade24-56d4-4728-8f43-e99807811b7a/brand-f469e29d2e0c2a89fb41.jpg","altText":"喜姐炸串品牌菜品图：酱汁臭豆腐（品牌宣传图）；来源：喜姐炸串品牌官网；https://www.xijiezhachuan.com/","reusePermission":"not independently confirmed; public source and credit retained"}]'::jsonb) as x("placeId" uuid,"title" text,"sourcePageUrl" text,"imageUrl" text,"credit" text,"branchEvidence" text,"sortOrder" integer,"sha256" text,"storagePath" text,"mimeType" text,"byteSize" bigint,"width" integer,"height" integer,"altText" text,"photoType" text,"reusePermission" text);
select id from public.places where id in (select "placeId" from photo_import) order by id for update;
do $$
begin
 if (select count(*) from photo_import) <> 10 then raise exception 'Unexpected import count'; end if;
 if exists(select 1 from photo_import i left join storage.objects o on o.bucket_id='place-media' and o.name=i."storagePath" where o.id is null or (o.metadata->>'size')::bigint <> i."byteSize" or o.metadata->>'mimetype' <> i."mimeType") then raise exception 'Storage object missing or metadata mismatch'; end if;
 if exists(select 1 from (select "placeId" as place_id,count(*) as additions from photo_import i where not exists(select 1 from public.place_media m where m.bucket_id='place-media' and m.storage_path=i."storagePath") group by "placeId") n where n.additions + (select count(*) from public.place_media m where m.place_id=n.place_id and m.lifecycle_status in ('ready','uploaded')) + coalesce((select cardinality(p.legacy_image_urls) from public.places p where p.id=n.place_id),0) > 5) then raise exception 'Five-photo limit exceeded'; end if;
end $$;
with inserted as (
 insert into public.place_media(place_id,uploaded_by,bucket_id,storage_path,mime_type,byte_size,width,height,alt_text,sort_order,lifecycle_status)
 select i."placeId",'298ab14f-c22b-4b74-9836-b0596d205cea'::uuid,'place-media',i."storagePath",i."mimeType",i."byteSize",i.width,i.height,i."altText",
 coalesce((select max(m.sort_order)+1 from public.place_media m where m.place_id=i."placeId" and m.lifecycle_status in ('ready','uploaded')),0)+i."sortOrder",'ready'
 from photo_import i
 on conflict (bucket_id,storage_path) do nothing
 returning id,place_id,storage_path
), logged as (
 insert into public.admin_audit_logs(actor_id,entity_type,entity_id,action,note,metadata)
 select null,'place_media',m.id::text,'place.media.import','用户要求从公开来源查找并上传店铺照片',
 jsonb_build_object('operator','codex_supabase_cli','batch','shop-photos-2026-10-17','place_id',m.place_id,'media_owner','298ab14f-c22b-4b74-9836-b0596d205cea','source_page_url',i."sourcePageUrl",'source_image_url',i."imageUrl",'credit',i.credit,'branch_evidence',i."branchEvidence",'sha256',i.sha256,'photo_type',i."photoType",'reuse_permission',i."reusePermission")
 from inserted m join photo_import i on i."storagePath"=m.storage_path
 returning id
)
select (select count(*) from inserted) as inserted_media,(select count(*) from logged) as audit_entries;
commit;
